    /**
     * Tests creating a new Distributor.
     *
     * @return    Distributor
     */
    public Distributor testCreate() throws Throwable {
    Distributor entity = null;

    LOGGER.info( "DistributorTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a Distributor");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Distributor" );

    try {
        entity = service.createDistributor( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getDistributorId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Distributor with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

