    /**
     * Tests getting all Distributors.
     *
     * @return    Collection
     */
    public List<Distributor> testGetAll() throws Throwable {
    LOGGER.info( "DistributorTest:testGetAll() - Retrieving Collection of Distributors:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Distributor : " );
    List<Distributor> collection  = null;

    try {
        // call the static get method on the DistributorService
        collection = service.getAllDistributor();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Distributor currEntity  = null;
            Iterator<Distributor> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDistributorId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

